import AppKit
import SwiftUI

/// 프로바이더 공식 로고 — 단색 SVG(24×24 viewBox)를 앱에 내장(base64)해 NSImage 로 렌더한다.
///
/// 출처: Simple Icons(claude·cursor·copilot/githubcopilot·openrouter) +
/// LobeHub icons(codex=OpenAI·antigravity·devin·grok·zai). 전부 검정 채움으로
/// 정규화했다 — 상태바에선 프로바이더 액센트색으로 마스킹하고, 앱 안에선 SwiftUI
/// template 렌더 + 프로바이더 액센트 tint 로 쓴다.
/// SVG 는 NSImage 가 macOS 11+ 에서 벡터로 읽으므로 어떤 크기로도 또렷하다.
@MainActor
enum ProviderIcons {
    /// 메뉴바 글리프 포인트 크기 — 공식 로고는 24×24 풀블리드(내부 여백 없음)라
    /// 기존 내장 아이콘(27pt·내부 여백 있음)보다 작은 표준 18pt 로 그린다.
    static let menuBarPointSize: CGFloat = 18

    /// providerID 에 내장 로고가 있는지.
    static func has(id: String) -> Bool { base64[id] != nil }

    /// 프로바이더 로고 NSImage (벡터 SVG 백킹, 검정 글리프). 앱 내 표시용.
    static func image(id: String) -> NSImage? {
        if let cached = rawCache[id] { return cached }
        guard let b64 = base64[id], let data = Data(base64Encoded: b64),
              let img = NSImage(data: data), img.isValid
        else { return nil }
        rawCache[id] = img
        return img
    }

    /// 메뉴바 표시용 — 템플릿 렌더 사본(원본 캐시와 분리해 크기/템플릿 설정이 섞이지 않게).
    static func menuBarImage(id: String) -> NSImage? {
        if let cached = menuBarCache[id] { return cached }
        guard let b64 = base64[id], let data = Data(base64Encoded: b64),
              let img = NSImage(data: data), img.isValid
        else { return nil }
        img.size = NSSize(width: menuBarPointSize, height: menuBarPointSize)
        img.isTemplate = true
        menuBarCache[id] = img
        return img
    }

    /// 상태바 표시용 컬러 로고 — 검정 SVG를 provider accent 색으로 마스킹한다.
    static func coloredMenuBarImage(id: String, colorHex: String) -> NSImage? {
        let cacheKey = "\(id)|\(colorHex)"
        if let cached = coloredMenuBarCache[cacheKey] { return cached }
        guard let raw = image(id: id) else { return nil }
        let size = NSSize(width: menuBarPointSize, height: menuBarPointSize)
        let out = NSImage(size: size)
        out.lockFocus()
        raw.draw(in: NSRect(origin: .zero, size: size), from: .zero, operation: .sourceOver, fraction: 1)
        (Palette.nsColor(fromHex: colorHex) ?? .labelColor).setFill()
        NSRect(origin: .zero, size: size).fill(using: .sourceIn)
        out.unlockFocus()
        out.isTemplate = false
        coloredMenuBarCache[cacheKey] = out
        return out
    }

    /// SwiftUI 용 템플릿 Image — 색은 호출부의 `foregroundStyle` 을 따른다.
    static func swiftUIImage(id: String) -> Image? {
        image(id: id).map { Image(nsImage: $0).renderingMode(.template) }
    }

    private static var rawCache: [String: NSImage] = [:]
    private static var menuBarCache: [String: NSImage] = [:]
    private static var coloredMenuBarCache: [String: NSImage] = [:]

    /// providerID → 정규화된 공식 로고 SVG (base64).
    private static let base64: [String: String] = [
        "claude": "",
        "codex": "",
        "cursor": "",
        "copilot": "",
        "antigravity": "",
        "devin": "",
        "grok": "",
        "openrouter": "",
        "zai": "",
    ]
}

extension NSColor {
    convenience init?(hex: String) {
        var hex = hex.trimmingCharacters(in: .whitespacesAndNewlines)
        if hex.hasPrefix("#") { hex.removeFirst() }
        guard hex.count == 6, let value = UInt32(hex, radix: 16) else { return nil }
        self.init(
            calibratedRed: CGFloat((value >> 16) & 0xff) / 255,
            green: CGFloat((value >> 8) & 0xff) / 255,
            blue: CGFloat(value & 0xff) / 255,
            alpha: 1
        )
    }
}
